def P(policy, col, mode='eps', eps=0.02, lam='1/5k'):
    r = pol[(pol['mode'] == mode) & (pol.eps == eps) & (pol.lam == lam) & (pol.policy == policy)].iloc[0]
    return r[col]

def Pci(policy, mode='eps', eps=0.02, lam='1/5k'):
    r = pol[(pol['mode'] == mode) & (pol.eps == eps) & (pol.lam == lam) & (pol.policy == policy)].iloc[0]
    return f"{E.capture(r.U, 'build_manuscript.py:40: r.U', f'.3f', -1)} [{E.capture(r.U_lo, 'build_manuscript.py:40: r.U_lo', f'.3f', -1)}, {E.capture(r.U_hi, 'build_manuscript.py:40: r.U_hi', f'.3f', -1)}]"

def pct(x):
    return f"{E.capture(100 * x, 'build_manuscript.py:43: 100 * x', f'.0f', -1)}%"

def A_(feature, mode, eps):
    return auc[(auc['mode'] == mode) & (auc.eps == eps) & (auc.feature == feature)].auc.iloc[0]

def best_gain(mode, eps):
    g = sw[(sw['mode'] == mode) & (sw.eps == eps)]
    r = g.loc[g.gain_over_best_corner.idxmax()]
    return r
